package com.agacostays.billing.security;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;@Component public class CurrentUserProvider{public Long userId(){try{return Long.valueOf(SecurityContextHolder.getContext().getAuthentication().getName());}catch(Exception e){return null;}}public String role(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?null:a.getAuthorities().stream().findFirst().map(x->x.getAuthority().replace("ROLE_","")).orElse(null);}}
